    public static function fromJson(array $data): self
    {
        return new self(
            kind: Kind::from(Json::string(Json::field($data, 'kind'))),
            message: Json::string(Json::field($data, 'message')),
            metadata: isset($data['metadata']) ? Json::map($data['metadata'], Json::string(...)) : null,
            reason: isset($data['reason']) ? Json::string($data['reason']) : null,
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        $data = ['kind' => $this->kind->value, 'message' => $this->message];
        if ($this->metadata !== null) {
            $data['metadata'] = (object) $this->metadata;
        }
        if ($this->reason !== null) {
            $data['reason'] = $this->reason;
        }
        return $data;
    }
}

/**
 * How fast a payment should land: `low`, `normal` and `high` pay the
 * network's rate now with its tip × 0.5, 1 or 2 (Ethereum's priority fee,
 * Bitcoin's rate above the mempool minimum, Solana's priority price); the
 * base part (Ethereum's base fee, Bitcoin's mempool minimum) is the
 * network's, so `low` is never below what nodes accept.
 */
enum FeeLevel: string
{
    case Low = 'low';
    case Normal = 'normal';
    case High = 'high';
}

/**
