/**
 * One job of the queue.
 */
final readonly class Job
{
    /**
     * @param bool $accepted Whether it was sent: a node accepted it, or may hold it (false for other kinds).
     * @param int $attempts Executions started since it was last fresh.
     * @param int $createdAt When it was queued, Unix ms.
     * @param ?int $deadline Not started after this, Unix ms; always present.
     * @param string $id The job id.
     * @param mixed $input What it was given; null for a kind given nothing (`prune`).
     * @param string $kind The job kind: its worker (`index`, `triggers`, `broadcast`, `prune`).
     * @param mixed $progress What its worker has done so far; always present.
     * @param ?string $reason Why it failed, or why its last attempt is being retried; always
     *     present.
     * @param int $runAt Not started before this, Unix ms: the next run of a pending job.
     * @param JobState $state Where it is.
     * @param string $topic What it locks: jobs whose topics conflict run one at a time, in line order.
     * @param ?string $txid A broadcast's transaction (txid), once recorded; always present,
     *     null before and for other kinds.
     * @param int $updatedAt When it was last written, Unix ms: started, retried or finished.
     */
    public function __construct(
        public bool $accepted,
        public int $attempts,
        public int $createdAt,
        public ?int $deadline,
        public string $id,
        public mixed $input,
        public string $kind,
        public mixed $progress,
        public ?string $reason,
        public int $runAt,
        public JobState $state,
        public string $topic,
        public ?string $txid,
        public int $updatedAt,
    ) {}

    /**
     * @param array<string, mixed> $data
     */
    public static function fromJson(array $data): self
    {
        return new self(
            accepted: Json::bool(Json::field($data, 'accepted')),
            attempts: Json::int(Json::field($data, 'attempts')),
            createdAt: Json::int(Json::field($data, 'created_at')),
            deadline: isset($data['deadline']) ? Json::int($data['deadline']) : null,
            id: Json::string(Json::field($data, 'id')),
            input: $data['input'] ?? null,
            kind: Json::string(Json::field($data, 'kind')),
            progress: $data['progress'] ?? null,
            reason: isset($data['reason']) ? Json::string($data['reason']) : null,
            runAt: Json::int(Json::field($data, 'run_at')),
            state: JobState::from(Json::string(Json::field($data, 'state'))),
            topic: Json::string(Json::field($data, 'topic')),
            txid: isset($data['txid']) ? Json::string($data['txid']) : null,
            updatedAt: Json::int(Json::field($data, 'updated_at')),
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        return [
            'accepted' => $this->accepted,
            'attempts' => $this->attempts,
            'created_at' => $this->createdAt,
            'deadline' => $this->deadline,
            'id' => $this->id,
            'input' => $this->input,
            'kind' => $this->kind,
            'progress' => $this->progress,
            'reason' => $this->reason,
            'run_at' => $this->runAt,
            'state' => $this->state->value,
            'topic' => $this->topic,
            'txid' => $this->txid,
            'updated_at' => $this->updatedAt,
        ];
    }
}

