/**
 * A setting as listed: its value, or for a secret one only whether it is
 * set: the first of its variants `$data` decodes as.
 */
function listedFromJson(mixed $data): Setting|SecretSetting
{
    return Json::first(
        $data,
        static fn(mixed $v): Setting => Setting::fromJson(Json::object($v)),
        static fn(mixed $v): SecretSetting => SecretSetting::fromJson(Json::object($v)),
    );
}

