/**
 * A mined leg with its transaction's txid and state (null for a reward or
 * an adjustment) and its block's time: a row of [`db::find_page`].
 */
final readonly class Movement
{
    /**
     * @param string $amount Exact atomic decimal text; signed for a reward or an adjustment.
     * @param ?string $amountUsd Its value in USD, exact decimal, signed as it adds to the balance
     *     (negative for a spent, burned or fee leg): `amount` in display units
     *     times its asset's USD price at its hour (its block's
     *     time, else when its transaction was recorded) when it was mined;
     *     null when there was none, while pending, and for an adjustment.
     *     Never filled later.
     * @param int $kind 0 received, 1 spent, 2 burned, 3 minted, 4 fee, 5 reward, 6
     *     adjustment (signed; leg 0: what the chain's balance read corrects the
     *     index's total by, at the position it was read at; leg 1: the coins a
     *     jump archived).
     * @param ?int $timestamp Its block's time, Unix seconds, when the node reported one.
     * @param ?string $totalReceivedUsd `total_received` in USD: each received leg's `amount_usd` (null: 0)
     *     added; `None` while pending.
     * @param ?string $totalSentUsd `total_sent` in USD: each sent leg's `amount_usd` (null: 0) added;
     *     `None` while pending.
     * @param string $walletIndexId The wallet index it is kept for: its address's index in its asset.
     * @param ?int $archivedAt A received coin a jump wrote off: that jump's position; never
     *     spendable again. Null otherwise.
     * @param ?string $block Its block; null while pending, and for an adjustment.
     * @param ?int $position Its block's position, or an adjustment's own; `None` while pending.
     * @param ?int $seq Its index's leg sequence: 1 + the highest the index has kept,
     *     unique per index; `None` while pending.
     * @param ?int $state 0 pending, 1 succeeded, 2 reverted.
     * @param ?string $total Its index's balance right after it; `None` while pending.
     * @param ?string $totalReceived What its index has received (received, minted, reward) through it;
     *     `None` while pending. No adjustment counts.
     * @param ?string $totalSent What its index has sent (spent, burned, fee) through it; `None` while
     *     pending. `total` is `total_received - total_sent` plus its index's
     *     adjustments so far.
     * @param ?string $transaction Its transaction; null for a reward or an adjustment.
     */
    public function __construct(
        public string $address,
        public string $amount,
        public ?string $amountUsd,
        public string $asset,
        public string $id,
        public int $kind,
        public int $legIndex,
        public ?int $timestamp,
        public ?string $totalReceivedUsd,
        public ?string $totalSentUsd,
        public string $walletIndexId,
        public ?int $archivedAt = null,
        public ?string $block = null,
        public ?int $coinIndex = null,
        public ?string $coinTxid = null,
        public ?int $position = null,
        public ?int $seq = null,
        public ?int $state = null,
        public ?string $total = null,
        public ?string $totalReceived = null,
        public ?string $totalSent = null,
        public ?string $transaction = null,
        public ?string $txid = null,
    ) {}

    /**
     * @param array<string, mixed> $data
     */
    public static function fromJson(array $data): self
    {
        return new self(
            address: Json::string(Json::field($data, 'address')),
            amount: Json::string(Json::field($data, 'amount')),
            amountUsd: isset($data['amount_usd']) ? Json::string($data['amount_usd']) : null,
            archivedAt: isset($data['archived_at']) ? Json::int($data['archived_at']) : null,
            asset: Json::string(Json::field($data, 'asset')),
            block: isset($data['block']) ? Json::string($data['block']) : null,
            coinIndex: isset($data['coin_index']) ? Json::int($data['coin_index']) : null,
            coinTxid: isset($data['coin_txid']) ? Json::string($data['coin_txid']) : null,
            id: Json::string(Json::field($data, 'id')),
            kind: Json::int(Json::field($data, 'kind')),
            legIndex: Json::int(Json::field($data, 'leg_index')),
            position: isset($data['position']) ? Json::int($data['position']) : null,
            seq: isset($data['seq']) ? Json::int($data['seq']) : null,
            state: isset($data['state']) ? Json::int($data['state']) : null,
            timestamp: isset($data['timestamp']) ? Json::int($data['timestamp']) : null,
            total: isset($data['total']) ? Json::string($data['total']) : null,
            totalReceived: isset($data['total_received']) ? Json::string($data['total_received']) : null,
            totalReceivedUsd: isset($data['total_received_usd']) ? Json::string($data['total_received_usd']) : null,
            totalSent: isset($data['total_sent']) ? Json::string($data['total_sent']) : null,
            totalSentUsd: isset($data['total_sent_usd']) ? Json::string($data['total_sent_usd']) : null,
            transaction: isset($data['transaction']) ? Json::string($data['transaction']) : null,
            txid: isset($data['txid']) ? Json::string($data['txid']) : null,
            walletIndexId: Json::string(Json::field($data, 'wallet_index_id')),
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        $data = [
            'address' => $this->address,
            'amount' => $this->amount,
            'amount_usd' => $this->amountUsd,
            'asset' => $this->asset,
            'id' => $this->id,
            'kind' => $this->kind,
            'leg_index' => $this->legIndex,
            'timestamp' => $this->timestamp,
            'total_received_usd' => $this->totalReceivedUsd,
            'total_sent_usd' => $this->totalSentUsd,
            'wallet_index_id' => $this->walletIndexId,
        ];
        if ($this->archivedAt !== null) {
            $data['archived_at'] = $this->archivedAt;
        }
        if ($this->block !== null) {
            $data['block'] = $this->block;
        }
        if ($this->coinIndex !== null) {
            $data['coin_index'] = $this->coinIndex;
        }
        if ($this->coinTxid !== null) {
            $data['coin_txid'] = $this->coinTxid;
        }
        if ($this->position !== null) {
            $data['position'] = $this->position;
        }
        if ($this->seq !== null) {
            $data['seq'] = $this->seq;
        }
        if ($this->state !== null) {
            $data['state'] = $this->state;
        }
        if ($this->total !== null) {
            $data['total'] = $this->total;
        }
        if ($this->totalReceived !== null) {
            $data['total_received'] = $this->totalReceived;
        }
        if ($this->totalSent !== null) {
            $data['total_sent'] = $this->totalSent;
        }
        if ($this->transaction !== null) {
            $data['transaction'] = $this->transaction;
        }
        if ($this->txid !== null) {
            $data['txid'] = $this->txid;
        }
        return $data;
    }
}

