/**
 * One network as stored: its `network` row, its `network_asset` rows, its
 * routes, its index and its `network_endpoint` nodes with their counts and
 * state.
 */
final readonly class StoredNetwork
{
    /**
     * @param list<NetworkAsset> $assets Its native currency and tokens.
     * @param int $blockTimeMs The chain's block (slot) time, in milliseconds.
     * @param string $chain Chain name.
     * @param ?string $chainId The chain's own id of the network (Ethereum chain id, Solana genesis
     *     hash); always present, null where the name is enough.
     * @param int $confirmations Positions below the tip before a block counts as confirmed.
     * @param bool $enabled Whether the server starts indexing it.
     * @param list<RpcNode> $endpoints Its nodes as stored, in failover order; none enabled: no call can go
     *     out, its index job idles and its payments wait.
     * @param ?string $explorerAddress An address's explorer page, `{address}` filled in; always present,
     *     null: none.
     * @param ?string $explorerTransaction A transaction's explorer page, `{tx}` filled in; always present,
     *     null: none.
     * @param ?int $maxDepth How many positions below the tip a wallet's start may be; at least
     *     `confirmations`. Always present, null: no limit. Null on a chain that
     *     reads balances (Solana, Ethereum): its line is the chain's final block.
     * @param string $network Network name.
     * @param list<RpcRoute> $routes Its routed methods, each over its own nodes; every other method goes
     *     to all of them.
     * @param mixed $settings The chain's own knobs; an absent key is the chain's default.
     * @param bool $testnet Whether its coins are test coins.
     */
    public function __construct(
        public array $assets,
        public int $blockTimeMs,
        public string $chain,
        public ?string $chainId,
        public int $confirmations,
        public bool $enabled,
        public array $endpoints,
        public ?string $explorerAddress,
        public ?string $explorerTransaction,
        public ?NetworkIndexing $index,
        public ?int $maxDepth,
        public string $network,
        public array $routes,
        public mixed $settings,
        public bool $testnet,
    ) {}

    /**
     * @param array<string, mixed> $data
     */
    public static function fromJson(array $data): self
    {
        return new self(
            assets: Json::list(
                Json::field($data, 'assets'),
                static fn(mixed $v): NetworkAsset => NetworkAsset::fromJson(Json::object($v)),
            ),
            blockTimeMs: Json::int(Json::field($data, 'block_time_ms')),
            chain: Json::string(Json::field($data, 'chain')),
            chainId: isset($data['chain_id']) ? Json::string($data['chain_id']) : null,
            confirmations: Json::int(Json::field($data, 'confirmations')),
            enabled: Json::bool(Json::field($data, 'enabled')),
            endpoints: Json::list(
                Json::field($data, 'endpoints'),
                static fn(mixed $v): RpcNode => RpcNode::fromJson(Json::object($v)),
            ),
            explorerAddress: isset($data['explorer_address']) ? Json::string($data['explorer_address']) : null,
            explorerTransaction: isset($data['explorer_transaction']) ? Json::string(
                $data['explorer_transaction'],
            ) : null,
            index: isset($data['index']) ? NetworkIndexing::fromJson(Json::object($data['index'])) : null,
            maxDepth: isset($data['max_depth']) ? Json::int($data['max_depth']) : null,
            network: Json::string(Json::field($data, 'network')),
            routes: Json::list(
                Json::field($data, 'routes'),
                static fn(mixed $v): RpcRoute => RpcRoute::fromJson(Json::object($v)),
            ),
            settings: Json::field($data, 'settings'),
            testnet: Json::bool(Json::field($data, 'testnet')),
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        return [
            'assets' => array_map(static fn(NetworkAsset $v): mixed => (object) $v->toJson(), $this->assets),
            'block_time_ms' => $this->blockTimeMs,
            'chain' => $this->chain,
            'chain_id' => $this->chainId,
            'confirmations' => $this->confirmations,
            'enabled' => $this->enabled,
            'endpoints' => array_map(static fn(RpcNode $v): mixed => (object) $v->toJson(), $this->endpoints),
            'explorer_address' => $this->explorerAddress,
            'explorer_transaction' => $this->explorerTransaction,
            'index' => $this->index === null ? null : (object) $this->index->toJson(),
            'max_depth' => $this->maxDepth,
            'network' => $this->network,
            'routes' => array_map(static fn(RpcRoute $v): mixed => (object) $v->toJson(), $this->routes),
            'settings' => $this->settings,
            'testnet' => $this->testnet,
        ];
    }
}

