            broadcastedAt: isset($data['broadcasted_at']) ? Json::int($data['broadcasted_at']) : null,
            chain: Json::string(Json::field($data, 'chain')),
            id: Json::string(Json::field($data, 'id')),
            legs: Json::list(Json::field($data, 'legs'), static fn(mixed $v): Leg => Leg::fromJson(Json::object($v))),
            network: Json::string(Json::field($data, 'network')),
            order: isset($data['order']) ? Json::int($data['order']) : null,
            position: isset($data['position']) ? Json::int($data['position']) : null,
            reason: isset($data['reason']) ? Json::string($data['reason']) : null,
            state: Json::int(Json::field($data, 'state')),
            txid: Json::string(Json::field($data, 'txid')),
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        $data = [
            'chain' => $this->chain,
            'id' => $this->id,
            'legs' => array_map(static fn(Leg $v): mixed => (object) $v->toJson(), $this->legs),
            'network' => $this->network,
            'state' => $this->state,
            'txid' => $this->txid,
        ];
        if ($this->block !== null) {
            $data['block'] = $this->block;
        }
        if ($this->broadcastedAt !== null) {
            $data['broadcasted_at'] = $this->broadcastedAt;
        }
        if ($this->order !== null) {
            $data['order'] = $this->order;
        }
        if ($this->position !== null) {
            $data['position'] = $this->position;
        }
        if ($this->reason !== null) {
            $data['reason'] = $this->reason;
        }
        return $data;
    }
