/**
 * One asset of one wallet being indexed, as every read answers it (the
 * API shows it as is): its columns, how far it is indexed against its
 * network's tip, its balances and its pending legs. All computed in SQL
 * (`wallet_index_with_balance`); amounts are exact atomic decimal text, never summed.
 * Positions are native (height or slot).
 */
final readonly class WalletIndex
{
    /**
     * @param string $asset The asset id.
     * @param int $birthday The start indexed from: the one asked for, or the first block the
     *     node served when it no longer served that one.
     * @param string $id `{wallet_id}.{asset}`.
     * @param int $requestedFrom The start asked for.
     * @param string $walletId `{chain}.{network}.{address}`.
     * @param ?string $balanceConfirmed Its confirmed balance: its last live mined leg's total at or below
     *     `finality_at`, `0` without one; negative when indexed debits exceed
     *     indexed credits (history before the start or a jump is unknown);
     *     null while `finality_at` is unknown.
     * @param ?string $balanceConfirmedReceived What it had received by then (that leg's `total_received`):
     *     `balance_confirmed` is `balance_confirmed_received -
     *     balance_confirmed_sent` plus its adjustments.
     * @param ?string $balanceConfirmedReceivedUsd What it had received by then in USD, each leg at its price when
     *     mined (that leg's `total_received_usd`; a leg without one adds 0).
     * @param ?string $balanceConfirmedSent What it had sent by then (fees included), the same way.
     * @param ?string $balanceConfirmedSentUsd What it had sent by then in USD, the same way (`total_sent_usd`).
     * @param ?string $balanceConfirmedSpendable What it can spend: `balance_confirmed` less its outgoing legs not yet
     *     in it (pending, or mined above `finality_at`); null while
     *     `balance_confirmed` is.
     * @param ?string $balancePending What it will hold once every pending transaction lands: its newest
     *     live mined leg's total, any block (`0` without one), with what this
     *     server sent and is not mined yet, in and out; null before its first
     *     block (`indexed_through`), as every balance is.
     * @param ?int $behindTip Blocks between `indexed_through` and the network's produced tip;
     *     null before the first block or without a tip.
     * @param ?int $finalityAt The network's final (confirmed) block: its indexer's, or a trigger
     *     round's; null when unknown.
     * @param ?int $indexedThrough The last block indexed; null before the first.
     * @param ?string $reason Why it is `no_data`; null otherwise.
     */
    public function __construct(
        public string $asset,
        public int $birthday,
        public string $id,
        public int $requestedFrom,
        public IndexState $state,
        public string $walletId,
        public ?string $balanceConfirmed = null,
        public ?string $balanceConfirmedReceived = null,
        public ?string $balanceConfirmedReceivedUsd = null,
        public ?string $balanceConfirmedSent = null,
        public ?string $balanceConfirmedSentUsd = null,
        public ?string $balanceConfirmedSpendable = null,
        public ?string $balancePending = null,
        public ?int $behindTip = null,
        public ?int $finalityAt = null,
        public ?int $indexedThrough = null,
        public ?string $reason = null,
    ) {}

    /**
     * @param array<string, mixed> $data
     */
    public static function fromJson(array $data): self
    {
        return new self(
            asset: Json::string(Json::field($data, 'asset')),
            balanceConfirmed: isset($data['balance_confirmed']) ? Json::string($data['balance_confirmed']) : null,
            balanceConfirmedReceived: isset($data['balance_confirmed_received']) ? Json::string(
                $data['balance_confirmed_received'],
            ) : null,
            balanceConfirmedReceivedUsd: isset($data['balance_confirmed_received_usd']) ? Json::string(
                $data['balance_confirmed_received_usd'],
            ) : null,
            balanceConfirmedSent: isset($data['balance_confirmed_sent']) ? Json::string(
                $data['balance_confirmed_sent'],
            ) : null,
            balanceConfirmedSentUsd: isset($data['balance_confirmed_sent_usd']) ? Json::string(
                $data['balance_confirmed_sent_usd'],
            ) : null,
            balanceConfirmedSpendable: isset($data['balance_confirmed_spendable']) ? Json::string(
                $data['balance_confirmed_spendable'],
            ) : null,
            balancePending: isset($data['balance_pending']) ? Json::string($data['balance_pending']) : null,
            behindTip: isset($data['behind_tip']) ? Json::int($data['behind_tip']) : null,
            birthday: Json::int(Json::field($data, 'birthday')),
            finalityAt: isset($data['finality_at']) ? Json::int($data['finality_at']) : null,
            id: Json::string(Json::field($data, 'id')),
            indexedThrough: isset($data['indexed_through']) ? Json::int($data['indexed_through']) : null,
            reason: isset($data['reason']) ? Json::string($data['reason']) : null,
            requestedFrom: Json::int(Json::field($data, 'requested_from')),
            state: IndexState::from(Json::string(Json::field($data, 'state'))),
            walletId: Json::string(Json::field($data, 'wallet_id')),
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        $data = [
            'asset' => $this->asset,
            'birthday' => $this->birthday,
            'id' => $this->id,
            'requested_from' => $this->requestedFrom,
            'state' => $this->state->value,
            'wallet_id' => $this->walletId,
        ];
        if ($this->balanceConfirmed !== null) {
            $data['balance_confirmed'] = $this->balanceConfirmed;
        }
        if ($this->balanceConfirmedReceived !== null) {
            $data['balance_confirmed_received'] = $this->balanceConfirmedReceived;
        }
        if ($this->balanceConfirmedReceivedUsd !== null) {
            $data['balance_confirmed_received_usd'] = $this->balanceConfirmedReceivedUsd;
        }
        if ($this->balanceConfirmedSent !== null) {
            $data['balance_confirmed_sent'] = $this->balanceConfirmedSent;
        }
        if ($this->balanceConfirmedSentUsd !== null) {
            $data['balance_confirmed_sent_usd'] = $this->balanceConfirmedSentUsd;
        }
        if ($this->balanceConfirmedSpendable !== null) {
            $data['balance_confirmed_spendable'] = $this->balanceConfirmedSpendable;
        }
        if ($this->balancePending !== null) {
            $data['balance_pending'] = $this->balancePending;
        }
        if ($this->behindTip !== null) {
            $data['behind_tip'] = $this->behindTip;
        }
        if ($this->finalityAt !== null) {
            $data['finality_at'] = $this->finalityAt;
        }
        if ($this->indexedThrough !== null) {
            $data['indexed_through'] = $this->indexedThrough;
        }
        if ($this->reason !== null) {
            $data['reason'] = $this->reason;
        }
        return $data;
    }
}

/**
 * `GET /v1/wallets`: a page of wallets.
 */
final readonly class WalletList
{
    /**
     * @param ?string $nextCursor Pass as `cursor` for the next page; null on the last page. Always
     *     present.
     * @param list<Wallet> $wallets Wallets in ID order.
     */
    public function __construct(public ?string $nextCursor, public array $wallets) {}

    /**
     * @param array<string, mixed> $data
     */
    public static function fromJson(array $data): self
    {
        return new self(
            nextCursor: isset($data['next_cursor']) ? Json::string($data['next_cursor']) : null,
            wallets: Json::list(
                Json::field($data, 'wallets'),
                static fn(mixed $v): Wallet => Wallet::fromJson(Json::object($v)),
            ),
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        return [
            'next_cursor' => $this->nextCursor,
            'wallets' => array_map(static fn(Wallet $v): mixed => (object) $v->toJson(), $this->wallets),
        ];
    }
}

/**
 * `PUT /v1/settings/{key}` body.
 */
final readonly class WriteSettingRequest
{
    /**
     * @param mixed $value Its new value: JSON of the setting's type.
     */
    public function __construct(public mixed $value) {}

    /**
     * @param array<string, mixed> $data
     */
    public static function fromJson(array $data): self
    {
        return new self(value: Json::field($data, 'value'));
    }

    /**
     * @return array<string, mixed>
     */
    public function toJson(): array
    {
        return ['value' => $this->value];
    }
}
